import { Request, Response, NextFunction } from 'express';
import { BadRequestError } from '../../shared/errors/BadRequestError';

// IDs are generated by apps/web/lib/offlineOperationId.ts (UUID v4 or
// op_<timestamp>_<random>). Keep the accepted alphabet deliberately narrow:
// no whitespace, control characters, commas, or header/log injection.
const OFFLINE_OPERATION_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/;

/**
 * Validate the optional offline idempotency key once, before route handlers.
 * A missing header is allowed for normal online requests; when present it
 * must be a single bounded token. Entity services still scope replay checks
 * to the authenticated owner and enforce durable uniqueness in the database.
 */
export const offlineOperationIdMiddleware = (
  req: Request,
  _res: Response,
  next: NextFunction
): void => {
  const raw = req.headers['x-offline-op-id'];
  if (raw === undefined) return next();

  if (typeof raw !== 'string' || !OFFLINE_OPERATION_ID_PATTERN.test(raw)) {
    return next(
      new BadRequestError(
        'X-Offline-Op-Id must be a single token of 1-128 safe characters',
        'OFFLINE_OP_ID_INVALID'
      )
    );
  }

  next();
};
